<?php
 namespace App\Http\Middleware; use Closure; class CORS { public function handle($request, Closure $next) { if (config('app.debug')) { $headers = [ 'Access-Control-Allow-Origin' => $request->header('Origin'), 'Access-Control-Allow-Methods' => 'POST, GET, OPTIONS, PUT, DELETE', 'Access-Control-Allow-Headers' => 'Content-Type, Accept, Authorization, Cookie, X-Requested-With, X-XSRF-TOKEN', 'Access-Control-Allow-Credentials' => 'true' ]; if ($request->isMethod('OPTIONS')) { return response()->make('', 200, $headers); } $response = $next($request); foreach ($headers as $key => $value) { $response->headers->set($key, $value); } return $response; } return $next($request); } } 